INSERT IGNORE INTO KennisbankArtikelen (Titel, Slug, Categorie, Samenvatting, Inhoud, Zichtbaar, Volgorde, AangemaaktOp) VALUES
('Wat is DNS en hoe werkt het?','dns-uitleg','DNS','DNS zet je domeinnaam om naar een IP-adres. Korte uitleg van hoe het werkt en waarom wijzigingen even duren.','## Wat is DNS?\n\nDNS (Domain Name System) vertaalt je domeinnaam — bijvoorbeeld voorbeeld.nl — naar het IP-adres van de server waar je website draait. Zonder DNS zouden bezoekers IP-adressen moeten onthouden.\n\n## Zo loopt een DNS-opvraging\n\n- De browser vraagt aan een DNS-resolver (van de internetprovider) om het IP-adres.\n- Die resolver vraagt het vervolgens aan de nameserver van het domein.\n- De nameserver antwoordt met het juiste record (A, AAAA, CNAME, MX...).\n\n## Waarom duurt een wijziging?\n\nDNS-antwoorden worden overal gecachet. Hoe lang dat duurt, staat in de TTL (time to live) van elk record. Verlaag voor een geplande verhuizing de TTL een dag van tevoren naar 300 seconden, dan schakelt vrijwel iedereen binnen enkele minuten over.',1,10,NOW()),
('A-record aanmaken of wijzigen','a-record-aanmaken','DNS','Het A-record koppelt je domein aan een IPv4-adres. Zo maak je er een aan of pas je hem aan.','## Wat is een A-record?\n\nEen A-record wijst een (sub)domein naar een IPv4-adres — het adres van je webserver. Voor www maak je meestal een tweede record aan, of een CNAME naar het hoofddomein.\n\n## Aanmaken of wijzigen\n\n- Log in op het klantportaal en ga naar Domeinen → DNS-beheer.\n- Kies het domein en voeg een record toe van het type A.\n- Vul als naam @ in voor het hoofddomein, of een subdomein zoals www of mail.\n- Vul bij waarde het IPv4-adres van je server in en sla op.\n\n## Let op\n\n- Een A-record en een CNAME met dezelfde naam kunnen niet naast elkaar bestaan.\n- Wijzigingen zijn zichtbaar zodra de oude TTL verlopen is; bij 300 seconden is dat binnen vijf minuten.',1,20,NOW()),
('CNAME-record instellen','cname-record','DNS','Een CNAME laat een subdomein verwijzen naar een andere domeinnaam. Handig voor www en externe diensten.','## Wat doet een CNAME?\n\nEen CNAME-record laat een naam als www.voorbeeld.nl verwijzen naar voorbeeld.nl — of naar een externe dienst zoals shop.platform.nl. De verwijzing volgt automatisch mee als het doel van IP verandert.\n\n## Wanneer gebruik je het?\n\n- www naar je hoofddomein laten wijzen.\n- Een subdomein koppelen aan een externe dienst die een hostnaam geeft.\n\n## Beperkingen\n\n- Op het hoofddomein (@) kan geen CNAME staan; gebruik daar een A/AAAA-record.\n- Een CNAME mag niet naast andere records met dezelfde naam bestaan.',1,30,NOW()),
('MX-records voor je e-mail instellen','mx-records','DNS','Met MX-records stuur je e-mail voor je domein naar de juiste mailserver. Zo stel je ze in en controleer je ze.','## Waarom MX-records?\n\nMX-records bepalen welke server e-mail voor je domein ontvangt. Staat het record fout, dan komt mail aan bij de verkeerde server of helemaal niet.\n\n## Instellen\n\n- Ga naar Domeinen → DNS-beheer en kies het domein.\n- Maak een MX-record met naam @ en als waarde de mailserver (bij ons pakket: mail.jouwdomein.nl of de opgegeven relayhost).\n- Prioriteit 10 is gebruikelijk; een tweede MX kan als fallback dienen.\n\n## Vergeet SPF niet\n\nMet een SPF-record (TXT) geef je aan welke servers namens jouw domein mogen mailen. Zonder SPF eindigen je berichten sneller in spam — zie ook het artikel over SPF, DKIM en DMARC.',1,40,NOW()),
('SPF, DKIM en DMARC goed instellen','spf-dkim-dmarc','DNS','Drie DNS-records die ervoor zorgen dat jouw mail aankomt en niemand namens jou kan spoofen.','## Waarom deze drie?\n\n- SPF zegt welke servers namens jouw domein mogen verzenden.\n- DKIM ondertekent elke mail zodat ontvangers zien dat hij echt van jou komt en ongewijzigd is.\n- DMARC vertelt ontvangers wat ze met verdachte mail moeten doen en rapporteert misbruik.\n\n## Instellen\n\n- SPF: maak een TXT-record @ met v=spf1 include:jouwmailserver ~all.\n- DKIM: kopieer het publieke DKIM-sleutelrecord uit je mail- of SMTP Relay-beheerpagina als TXT-record.\n- DMARC: TXT-record _dmarc met v=DMARC1; p=quarantine; rua=mailto:dmarc@jouwdomein.nl.\n\n## Testen\n\nStuur een testmail naar een mail-tester of bekijk de headers van een ontvangen mail: daar zie je SPF, DKIM en DMARC als "pass".',1,50,NOW()),
('TTL verlagen voor een verhuizing','ttl-verlagen','DNS','Verlaag je TTL een dag voor de verhuizing en je DNS-wijziging is binnen minuten actief in plaats van uren.','## Waarom een lage TTL?\n\nDe TTL bepaalt hoe lang DNS-resolvers jouw records onthouden. Staat die op 24 uur, dan kan een verhuizing een dag lang half over zijn: de ene bezoeker komt op de oude server, de ander op de nieuwe.\n\n## Plan van aanpak\n\n- Zet 24 uur voor de verhuizing de TTL van je A-, AAAA-, CNAME- en MX-records op 300 seconden.\n- Wacht tot de oude TTL verlopen is.\n- Voer dan de DNS-wijziging door: binnen enkele minuten ziet vrijwel iedereen de nieuwe instellingen.\n- Verhoog daarna de TTL weer naar 3600 of 86400 om je nameservers te ontlasten.',1,60,NOW()),
('Bedrijfsgegevens wijzigen (adres, e-mail, telefoon)','bedrijfsgegevens-wijzigen','Administratie','Zo pas je je factuuradres en contactgegevens aan in het klantportaal.','## Waar wijzig je je gegevens?\n\nLog in op het klantportaal en ga naar Mijn gegevens. Daar pas je je bedrijfsnaam, adres, e-mailadres en telefoonnummer aan.\n\n## Wat wordt bijgewerkt?\n\n- Nieuwe facturen en offertes tonen direct de nieuwe gegevens.\n- Het e-mailadres gebruiken we voor facturen, storingmeldingen en wachtwoordresets — houd het actueel.\n\n## KvK of btw-nummer veranderd?\n\nNeem dan even contact op via een ticket. Die gegevens moeten wij aanpassen, omdat ze op alle toekomstige facturen correct moeten staan.',1,10,NOW()),
('Facturen betalen en downloaden','facturen-betalen','Administratie','In het klantportaal vind je al je facturen: downloaden, betalen en herinneringen bijhouden.','## Je facturen vinden\n\nIn het klantportaal onder Facturen zie je alle open en betaalde facturen. Per factuur download je een PDF en zie je de betaalstatus.\n\n## Betalen\n\n- Betaal via de betaallink op de factuur (iDEAL en andere methoden).\n- Handmatig overmaken kan ook; vermeld dan altijd het factuurnummer.\n\n## Te laat betaald?\n\nBij een achterstand krijg je eerst een herinnering, daarna een aanmaning. Zijn er vragen over een factuur? Open dan een ticket — graag met het factuurnummer erbij.',1,20,NOW()),
('Betaalgegevens en incasso wijzigen','betaalgegevens-wijzigen','Administratie','Nieuw rekeningnummer of andere betaalwijze? Zo regel je het.','## Betaalwijze aanpassen\n\nGa in het klantportaal naar Mijn gegevens → Betaling. Daar kies je de gewenste betaalwijze en pas je je rekeningnummer aan.\n\n## Incasso activeren\n\n- Vul je IBAN in en bevestig de machtiging.\n- Incasso''s lopen op de betaaldatum van de factuur; je krijgt vooraf altijd de factuur per mail.\n\n## Let op\n\nEen gewijzigd rekeningnummer geldt voor toekomstige incasso''s. Een al aangeboden incasso kun je binnen acht weken bij je bank laten storneren.',1,30,NOW()),
('Contactpersonen en subaccounts toevoegen','contactpersonen-toevoegen','Administratie','Geef collega''s of een externe boekhouder eigen toegang tot je klantportaal.','## Waarom subaccounts?\n\nWerkt een collega mee aan tickets, of moet je boekhouder alleen facturen zien? Maak dan een apart account aan in plaats van je inloggegevens te delen.\n\n## Toevoegen\n\n- Ga naar Mijn gegevens → Contactpersonen.\n- Kies Toevoegen en vul naam en e-mailadres in.\n- Kies de rol: bijvoorbeeld alleen financieel, of volledige toegang.\n\n## Beveiliging\n\nIedere contactpersoon krijgt een eigen login en kan tweestapsverificatie aanzetten. Verwijder accounts meteen als iemand uit dienst gaat.',1,40,NOW()),
('Contracten en looptijd inzien','contracten-inzien','Administratie','Waar je in het portaal ziet welke diensten lopen en wanneer ze verlengen.','## Je contracten\n\nOnder Diensten of Contracten in het klantportaal staat welke diensten je afneemt, met de looptijd en verlengdatum. Verlenging gebeurt automatisch, tenzij je voor de opzegtermijn opzegt.\n\n## Opzegtermijn\n\nDe opzegtermijn staat bij elke dienst vermeld. Zeg je op tijd op, dan loopt de dienst tot het einde van de contractperiode — je houdt dus waar je voor betaald hebt.\n\n## Opzeggen\n\nZeg diensten op via het portaal of een ticket. We bevestigen de opzegging per e-mail met de einddatum.',1,50,NOW()),
('Tweestapsverificatie (2FA) aanzetten','2fa-aanzetten','Administratie','Beveilig je klantportaal-account met een extra stap naast je wachtwoord.','## Waarom 2FA?\n\nMet alleen een wachtwoord kan iemand die dat wachtwoord heeft direct bij je facturen en diensten. Met 2FA is ook een code van je telefoon nodig — gestolen wachtwoorden zijn dan vrijwel waardeloos.\n\n## Aanzetten\n\n- Ga naar Mijn gegevens → Beveiliging → Tweestapsverificatie.\n- Scan de QR-code met een authenticator-app (Google Authenticator, 1Password, ...).\n- Voer de gegenereerde code in om te bevestigen.\n\n## Herstelcodes\n\nBewaar de herstelcodes die je krijgt op een veilige plek — daarmee kom je erin als je telefoon kwijt is.',1,60,NOW()),
('Een domeinnaam registreren','domeinnaam-registreren','Domeinen','Zo registreer je een nieuwe domeinnaam in een paar minuten.','## Registreren\n\n- Zoek je gewenste naam in de domeincheck op onze site.\n- Kies de extensie (.nl, .com, .be...) en rond de bestelling af.\n- De registratie is meestal binnen enkele minuten actief; .nl is vrijwel direct.\n\n## Na de registratie\n\n- Zet de nameservers of DNS-records goed via Domeinen → DNS-beheer.\n- Zet een SSL-certificaat aan op je hosting.\n\n## Bescherming\n\nDomeinen staan standaard op auto-renew, zodat je ze niet per ongeluk kwijtraakt. Controleer wel dat je registratiegegevens kloppen — daar gaat de WHOIS-informatie over.',1,10,NOW()),
('Domein verhuizen met een verhuiscode (EPP)','domein-verhuizen-epp','Domeinen','Met de authcode verhuis je je domein naar een andere registrar zonder downtime.','## Wat heb je nodig?\n\nEen verhuiscode (EPP/authcode) van je huidige registrar. Die vraag je op in hun beheerpaneel of via support.\n\n## Verhuizing starten\n\n- Dien de verhuisaanvraag in bij ons met de verhuiscode.\n- Bevestig eventuele goedkeuringsmails van de oude registrar.\n- De meeste verhuizingen zijn binnen enkele uren tot een dag rond.\n\n## Zonder downtime\n\nLaat je DNS voor de verhuizing al naar de nieuwe nameservers wijzen (of kopieer je DNS-records), dan blijft je site bereikbaar terwijl het domein administratief overstapt. Zie ook het artikel over TTL verlagen.',1,20,NOW()),
('Nameservers wijzigen','nameservers-wijzigen','Domeinen','Zo zet je je domein op onze nameservers — of juist naar externe DNS.','## Waarom nameservers?\n\nDe nameservers bepalen bij welke partij je DNS-records worden beheerd. Op onze nameservers beheer je alles via het klantportaal.\n\n## Wijzigen\n\n- Ga naar Domeinen, kies het domein en open Nameservers.\n- Kies onze nameservers (of vul eigen nameservers in) en sla op.\n- De wijziging kan tot 24 uur duren om overal door te sijpelen.\n\n## Let op\n\nNa de wijziging beheer je DNS alleen nog bij de nieuwe nameserver-provider. Records bij de oude provider doen dan niets meer.',1,30,NOW()),
('WHOIS-gegevens en privacy','whois-privacy','Domeinen','Welke gegevens publiek zichtbaar zijn bij je domein — en hoe privacy-bescherming werkt.','## Wat is WHOIS?\n\nIn het WHOIS-register staat wie een domein registreerde. Welke gegevens zichtbaar zijn, verschilt per extensie en is sinds de AVG steeds beperkter.\n\n## Privacy-bescherming\n\n- Bij .nl worden particuliere gegevens al gemaskeerd.\n- Bij andere extensies kun je vaak WHOIS-privacy activeren: jouw gegevens blijven bij de registrar, het register toont een contactformulier.\n\n## Gegevens kloppen\n\nVooral het e-mailadres moet kloppen: daarnaar gaan verificatie- en verhuisberichten. Pas je gegevens aan via Domeinen → Registratiegegevens.',1,40,NOW()),
('Domein forwarden (doorverwijzen)','domein-forwarden','Domeinen','Laat bezoekers van een extra domein automatisch doorklikken naar je hoofdsite.','## Wanneer forwarden?\n\nHeb je meerdere extensies of varianten van je naam? Met een forward stuur je die allemaal naar je hoofddomein — geen aparte website nodig.\n\n## Instellen\n\n- Ga naar Domeinen → Doorverwijzingen.\n- Kies het doeladres (https://www.jouwdomein.nl) en het type: 301 (permanent, beste voor SEO).\n- Bij een URL-forward werkt ook https; bij een DNS-redirect controleer je of SSL op het doel actief is.\n\n## E-mail\n\nDoorverwijzen geldt alleen voor het domein/web; voor e-mail op dat domein heb je aparte MX-records of een alias nodig.',1,50,NOW()),
('Subdomein aanmaken','subdomein-aanmaken','Domeinen','Zet bijvoorbeeld shop. of staging. voor je domein met een eigen record of aparte site.','## Twee manieren\n\n- Via DNS: maak een A- of CNAME-record voor het subdomein dat naar een server of externe dienst wijst.\n- Via het hostingpaneel: maak het subdomein aan als eigen site met eigen document-root en SSL.\n\n## Wanneer welke?\n\n- Aparte applicatie op eigen hosting? Maak het subdomein in het hostingpaneel aan.\n- Alleen doorverwijzen naar iets externs (winkelplatform, statuspagina)? Volstaat een DNS-record.',1,60,NOW()),
('Bestanden uploaden met FTP/SFTP','bestanden-uploaden-ftp','Hosting','Zet je website online met een FTP-programma of de bestandsbeheerder.','## Toegang\n\nJe FTP-gegevens (host, gebruikersnaam, wachtwoord, poort) vind je in het klantportaal bij je hostingdienst. Kies SFTP (poort 22) als je client dat ondersteunt — dat is versleuteld.\n\n## Uploaden\n\n- Gebruik FileZilla, WinSCP of de bestandsbeheerder in het paneel.\n- Publiceer bestanden in de map public_html (of de document-root van het domein).\n- Je indexbestand moet index.php of index.html heten.\n\n## Handig\n\n- Leeg de oude bestanden alleen als je zeker weet dat je ze niet meer nodig hebt.\n- Bewaar schrijfrechten strak: mappen op 755, bestanden op 644 — geen 777.',1,10,NOW()),
('Een database aanmaken en koppelen','database-aanmaken','Hosting','Voor WordPress en andere apps heb je een database nodig. Zo maak je er een.','## Aanmaken\n\n- Ga in het klantportaal naar je hostingdienst → Databases.\n- Maak een database en een databasegebruiker aan, en koppel de gebruiker met alle rechten.\n\n## Verbinden\n\n- Gebruik in je applicatie: host localhost, plus de databasenaam, gebruiker en het wachtwoord.\n- Bij WordPress zet je die gegevens in wp-config.php.\n\n## Beheer\n\nVia phpMyAdmin (in het paneel) beheer je tabellen, importeer en exporteer je backups en voer je queries uit. Maak voor grote imports eerst een export — dan kun je altijd terug.',1,20,NOW()),
('E-mailaccount aanmaken','emailaccount-aanmaken','Hosting','Een eigen mailbox op jouw domein: zo maak je hem aan en koppel je hem aan je mailprogramma.','## Aanmaken\n\n- Ga naar je hostingdienst → E-mail → Mailbox aanmaken.\n- Kies het adres (info@jouwdomein.nl) en een sterk wachtwoord.\n\n## Instellen op je apparaat\n\n- IMAP: mail.jouwdomein.nl, poort 993 (SSL).\n- SMTP: mail.jouwdomein.nl, poort 465 of 587 (SSL/STARTTLS).\n- Gebruikersnaam is je volledige e-mailadres.\n\n## Webmail\n\nOnderweg? Log in op onze webmail met je e-mailadres en wachtwoord — geen installatie nodig.',1,30,NOW()),
('SSL (HTTPS) activeren voor je site','ssl-activeren','Hosting','Zet je site op HTTPS met een gratis certificaat dat zichzelf vernieuwt.','## Activeren\n\n- Ga naar je hostingdienst → SSL-certificaten en kies het domein.\n- Activeer het gratis Let''s Encrypt-certificaat; dat gebeurt binnen enkele minuten.\n- Vergeet www en eventuele subdomeinen niet.\n\n## Alles via HTTPS\n\n- Zet een 301-redirect van http naar https.\n- Pas absolute links en afbeeldingspaden aan naar https:// om mixed-content-waarschuwingen te voorkomen.\n\n## Automatisch vernieuwen\n\nHet certificaat vernieuwt automatisch — je hoeft er verder niets aan te doen.',1,40,NOW()),
('Cronjobs (geplande taken) instellen','cronjobs-instellen','Hosting','Laat taken zoals nieuwsbrieven of imports automatisch op vaste tijden draaien.','## Waarvoor cron?\n\nVoor terugkerende taken: sitemap genereren, mails versturen, database opschonen, feeds ophalen.\n\n## Instellen\n\n- Ga naar je hostingdienst → Cronjobs.\n- Kies het interval (elke 5 minuten, dagelijks om 3:00, maandag, ...) en geef het commando, bijvoorbeeld: php /home/gebruiker/domains/site.nl/cron.php.\n- Gebruik waar mogelijk het hele pad naar php en het script.\n\n## Tips\n\n- Laat output niet ongemailed opstapelen; log naar een bestand.\n- Draai zware jobs buiten piekuren.',1,50,NOW()),
('WordPress installeren in een paar klikken','wordpress-installeren','Hosting','Installeer WordPress snel via het hostingpaneel — met database en al.','## Installatie\n\n- Ga naar je hostingdienst → Applicatie-installer en kies WordPress.\n- Kies het domein, eventueel een map, en rond af: database, admin-account en basisinstellingen worden klaargezet.\n- Log daarna in op /wp-admin.\n\n## Direct daarna\n\n- Kies een licht thema en installeer alleen de plugins die je echt nodig hebt.\n- Zet HTTPS aan (zie het SSL-artikel) en werk WordPress, thema en plugins bij.\n\n## Updates en veiligheid\n\nKleine beveiligingsupdates installeert WordPress automatisch. Maak bij elke grote update eerst een back-up — bij onze pakketten draait er dagelijks al een automatische.',1,60,NOW()),
('Je eerste Cloud VPS bestellen en klaarmaken','cloudvps-eerste-vps','Cloud VPS','Bestel een VPS, kies een OS en log voor het eerst in via SSH.','## Bestellen\n\n- Kies je pakket (vCPU, RAM, opslag) in de configurator.\n- Kies het besturingssysteem: Ubuntu of Debian voor webservers zijn de meest gekozen opties.\n- Rond de bestelling af; de VPS staat er meestal binnen een paar minuten.\n\n## Eerste login\n\n- Log in via SSH als root: ssh root@jouw-server-ip — met het wachtwoord uit het klantportaal.\n- Maak meteen een gewone gebruiker aan met sudo-rechten en schakel root-login via wachtwoord uit.\n\n## Basis beveiliging\n\n- Voer direct apt update && apt upgrade uit.\n- Zet een firewall aan (ufw) en sta alleen de poorten toe die je gebruikt (22, 80, 443).',1,10,NOW()),
('SSH-sleutels instellen','cloudvps-ssh-keys','Cloud VPS','Veiliger inloggen zonder wachtwoord: zo genereer en gebruik je een SSH-key.','## Sleutelpaar maken\n\n- Genereer op je eigen computer een sleutel: ssh-keygen -t ed25519.\n- Publieke sleutel staat in ~/.ssh/id_ed25519.pub; de privesleutel blijft geheim.\n\n## Op de VPS zetten\n\n- Kopieer de publieke sleutel naar de server met ssh-copy-id gebruiker@jouw-server-ip, of plak hem in ~/.ssh/authorized_keys.\n- Test daarna inloggen: ssh gebruiker@jouw-server-ip zonder wachtwoord.\n\n## Wachtwoordlogin uit\n\n- Zet in /etc/ssh/sshd_config: PasswordAuthentication no en herstart SSH.\n- Houd een sessie open terwijl je test, zodat je jezelf niet buitensluit.',1,20,NOW()),
('Webserver installeren (Nginx + PHP-FPM)','cloudvps-nginx-php','Cloud VPS','De klassieke stack op je VPS: Nginx, PHP-FPM en MariaDB in tien minuten.','## Installatie\n\n- Installeer Nginx, PHP-FPM en MariaDB: apt install nginx php-fpm php-mysql mariadb-server.\n- Beveilig MariaDB met mysql_secure_installation.\n- Richt een serverblok in /etc/nginx/sites-available in met fastcgi_pass naar de PHP-FPM-socket.\n\n## Testen\n\n- Zet een index.php met phpinfo() in je document-root en controleer in de browser.\n- Daarna: SSL-certificaat met certbot --nginx voor gratis HTTPS.\n\n## Performance\n\n- Zet PHP opcache aan en pas pm.max_children aan op je RAM.\n- Statische bestanden serveert Nginx vanzelf; dynamische gaan naar PHP-FPM.',1,30,NOW()),
('Je VPS monitoren en backups instellen','cloudvps-monitoring-backups','Cloud VPS','Houd je VPS gezond: resource-monitoring, alerts en een backup-schema.','## Monitoren\n\n- Bekijk CPU, geheugen en disk in het klantportaal bij je VPS.\n- Op de server: htop en df -h voor een snelle check.\n- Zet waar nodig een alerting-tool (bijv. netdata) of laat je uptime monitoren door een externe service.\n\n## Backups\n\n- Gebruik onze VPS-snapshots voor volledige images, en/of script je eigen dumps: database plus belangrijke mappen.\n- Richt op de 3-2-1-regel: 3 kopieen, 2 media, 1 offsite.\n- Test restores regelmatig — een ongeteste backup is geen backup.\n\n## Updates\n\nAutomatische beveiligingsupdates (unattended-upgrades) aanbevelen; kernel-updates vereisen een herstart.',1,40,NOW()),
('VPS upgraden of downgraden','cloudvps-upgraden','Cloud VPS','Meer CPU, RAM of opslag nodig? Zo schaal je je VPS zonder verlies.','## Opschalen\n\n- Vraag de upgrade aan in het klantportaal bij je VPS.\n- Meestal is een korte herstart nodig; er gaat geen data verloren.\n- Disk-uitbreidingen zijn definitief en kunnen niet ongedaan worden gemaakt.\n\n## Wanneer upgraden?\n\n- CPU duurzaam boven de 80% bij normale load.\n- Geheugen tegen swap aan — je site voelt traag.\n- Disk boven de 80% vol: ruim op, of vergroot.\n\n## Downgraden\n\nKleiner maken kan meestal alleen via een nieuwe VPS met migratie. Vraag via een ticket advies voordat je opslaat.',1,50,NOW()),
('Firewall instellen met UFW','cloudvps-ufw-firewall','Cloud VPS','Sta alleen de poorten toe die je gebruikt — met vijf commando''s is je basis-firewall klaar.','## UFW inschakelen\n\n- Installeer en sta toe wat je nodig hebt: ufw allow ssh, ufw allow http, ufw allow https.\n- Schakel in met ufw enable en check de status met ufw status.\n\n## Extra regels\n\n- Sta je databaspoort (3306) alleen toe vanaf specifieke IP''s: ufw allow from 1.2.3.4 to any port 3306.\n- Verwijder overbodige regels: ufw delete allow <regel>.\n\n## Let op\n\nZorg dat SSH (poort 22 of je eigen poort) is toegestaan voordat je ufw enable doet — anders sluit je jezelf uit.',1,60,NOW());
